SELECT COUNT(1)
FROM rbac_permission
WHERE account_id = #{accountId} AND deleted = 0

    AND perm_code LIKE CONCAT('%', #{permCode}, '%')


    AND perm_name LIKE CONCAT('%', #{permName}, '%')


    AND perm_type = #{permType}


    AND parent_id = #{parentId}


    AND status = #{status}

SELECT id, account_id, perm_code, perm_name, perm_type, parent_id, path, method, status, system_managed, deleted, create_time, update_time
FROM rbac_permission
WHERE account_id = #{accountId} AND deleted = 0

    AND perm_code LIKE CONCAT('%', #{permCode}, '%')


    AND perm_name LIKE CONCAT('%', #{permName}, '%')


    AND perm_type = #{permType}


    AND parent_id = #{parentId}


    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{pageSize}
